# c400: 산성 폭발 처음 30% · 터질 때 피해 3 → 다 강화 10
C400_R = [('const CH_ACID_HIT = 5;   /* c399: 10 → 5 */', "const chAcidHit = () => Math.round(3 + 7 * lv('acid') / 5);   /* c400: 터질 때 피해 — 처음 3, 다 강화하면 10 (3 · 4 · 6 · 7 · 9 · 10) */   /* c399: 5 */"), ('CH_ACID_HIT', 'chAcidHit()', 7), ('if (Math.random() >= 0.2 + 0.1 * n) return;   /* c399: 처음 20% · 강화마다 +10% */', 'if (Math.random() >= 0.3 + 0.1 * n) return;   /* c400: 처음 30% · 강화마다 +10% */   /* c399: 20% */'), ('20 + 10 * n', '30 + 10 * n', 2), ('터질 확률 ${30 + 10 * n}% · 터질 때 5 ·', '터질 확률 ${30 + 10 * n}% · 터질 때 ${Math.round(3 + 7 * n / 5)} ·'), ('바로 5의 피해', '바로 3의 피해(강화하면 10까지)')]
